export function cameraOrientationToDegrees(orientation) {
    switch (orientation) {
        case 'up':
            return 0;
        case 'right':
            return 90;
        case 'down':
            return 180;
        case 'left':
            return 270;
    }
}
export function rotateBy(degrees, byDegrees) {
    const rotated = degrees + byDegrees;
    return rotated % 360;
}
